css:
.hero {
  position: relative;
  height: 200px;
  max-width: 420px;
  overflow: hidden; /* clip the image to the box */
  border-radius: 8px;
  background: #3f3f46;
}

.photo {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  background: #fed7aa;
}

.caption {
  position: absolute;
  inset: auto 0 0 0; /* stretch along the bottom edge */
  padding: 12px 16px;
  background: rgb(24 24 27 / 0.7);
  color: #fafafa;
}
